    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof generateAuditReport>>, TError,{data: BodyType<AuditReportInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof generateAuditReport>>, TError,{data: BodyType<AuditReportInput>}, TContext> => {

const mutationKey = ['generateAuditReport'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof generateAuditReport>>, {data: BodyType<AuditReportInput>}> = (props) => {
          const {data} = props ?? {};

          return  generateAuditReport(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type GenerateAuditReportMutationResult = NonNullable<Awaited<ReturnType<typeof generateAuditReport>>>
    export type GenerateAuditReportMutationBody = BodyType<AuditReportInput>
    export type GenerateAuditReportMutationError = ErrorType<unknown>

    /**
 * @summary Generate and persist an audit report
 */
export const useGenerateAuditReport = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof generateAuditReport>>, TError,{data: BodyType<AuditReportInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof generateAuditReport>>,
        TError,
        {data: BodyType<AuditReportInput>},
        TContext
      > => {
      return useMutation(getGenerateAuditReportMutationOptions(options));
    }

